WITH inner_cte AS ( SELECT atp.TERM_CODE, atp.TERM_DESCRIPTION, at.ACADEMIC_YEAR, COUNT(ss.SUBJECT_ID) AS subject_count, SUM(ss.SUBJECT_ENROLLMENT_NUMBER) AS total_enrollment FROM ACADEMIC_TERM_PARAMETER atp JOIN ACADEMIC_TERMS at ON atp.TERM_CODE = at.TERM_CODE JOIN SUBJECT_SUMMARY ss ON at.TERM_CODE = ss.TERM_CODE WHERE atp.IS_CURRENT_TERM = 'Y' GROUP BY atp.TERM_CODE, atp.TERM_DESCRIPTION, at.ACADEMIC_YEAR ), AcademicYearDesc AS ( SELECT ACADEMIC_YEAR, MAX(ACADEMIC_YEAR_DESC) AS ACADEMIC_YEAR_DESC FROM ACADEMIC_TERMS GROUP BY ACADEMIC_YEAR ), DeptCounts AS ( SELECT at.TERM_CODE, ss.DEPARTMENT_NAME, COUNT(ss.SUBJECT_ID) AS dept_subject_count FROM ACADEMIC_TERMS at JOIN SUBJECT_SUMMARY ss ON at.TERM_CODE = ss.TERM_CODE GROUP BY at.TERM_CODE, ss.DEPARTMENT_NAME ), DeptRanked AS ( SELECT dc.TERM_CODE, dc.DEPARTMENT_NAME, dc.dept_subject_count, RANK() OVER (PARTITION BY dc.TERM_CODE ORDER BY dc.dept_subject_count DESC) AS dept_rank FROM DeptCounts dc ) SELECT ict.TERM_CODE, ict.TERM_DESCRIPTION, ict.ACADEMIC_YEAR, ict.subject_count, ict.total_enrollment, ayd.ACADEMIC_YEAR_DESC, dr.DEPARTMENT_NAME AS most_prominent_department, dr.dept_subject_count AS department_subject_count FROM inner_cte ict JOIN AcademicYearDesc ayd ON ict.ACADEMIC_YEAR = ayd.ACADEMIC_YEAR LEFT JOIN DeptRanked dr ON ict.TERM_CODE = dr.TERM_CODE AND dr.dept_rank = 1 ORDER BY ict.TERM_CODE;